-- Exact five independently accepted unnumbered Japanese Awakening Trainer fronts053-057. Previously published Pokemon051/052 remain outside this finite scope.
-- Private full metadata evidence, separate bounded constant-array reads.
BEGIN READ ONLY;
SET LOCAL statement_timeout = '20s';
SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=any(ARRAY['05ec5ae6-bfb8-41b1-a65b-acb7ce4c3585'::uuid,'56fc9f48-441c-40da-b1a7-29fdbd5300c4'::uuid,'6196aadb-f7bc-4449-8fd3-254987e292f8'::uuid,'ecd63564-d5d4-402d-b28d-95011e2a9107'::uuid,'f03f92e7-086a-4ec9-8281-e3c88906d13d'::uuid]::uuid[]) ORDER BY identity LIMIT 6;
SELECT 'variants' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_variants t WHERE printing_id=any(ARRAY['05ec5ae6-bfb8-41b1-a65b-acb7ce4c3585'::uuid,'56fc9f48-441c-40da-b1a7-29fdbd5300c4'::uuid,'6196aadb-f7bc-4449-8fd3-254987e292f8'::uuid,'ecd63564-d5d4-402d-b28d-95011e2a9107'::uuid,'f03f92e7-086a-4ec9-8281-e3c88906d13d'::uuid]::uuid[]) ORDER BY identity LIMIT 6;
SELECT 'names' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_names t WHERE printing_id=any(ARRAY['05ec5ae6-bfb8-41b1-a65b-acb7ce4c3585'::uuid,'56fc9f48-441c-40da-b1a7-29fdbd5300c4'::uuid,'6196aadb-f7bc-4449-8fd3-254987e292f8'::uuid,'ecd63564-d5d4-402d-b28d-95011e2a9107'::uuid,'f03f92e7-086a-4ec9-8281-e3c88906d13d'::uuid]::uuid[]) ORDER BY identity LIMIT 11;
SELECT 'sets' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.sets t WHERE id='a15481a7-410b-4a98-8695-3bba0db9d226'::uuid ORDER BY identity LIMIT 2;
SELECT 'assets' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.assets t WHERE printing_id=any(ARRAY['05ec5ae6-bfb8-41b1-a65b-acb7ce4c3585'::uuid,'56fc9f48-441c-40da-b1a7-29fdbd5300c4'::uuid,'6196aadb-f7bc-4449-8fd3-254987e292f8'::uuid,'ecd63564-d5d4-402d-b28d-95011e2a9107'::uuid,'f03f92e7-086a-4ec9-8281-e3c88906d13d'::uuid]::uuid[]) OR variant_id=any(ARRAY['40806ca5-1d4c-4bf6-b499-cee8ff167f94'::uuid,'767914af-5fcc-4e7c-9304-de89589eb56f'::uuid,'7d0611e3-9b65-4539-8803-c7a9876f6e68'::uuid,'eaa7573e-3860-440e-be69-cb414e6bbda5'::uuid,'fc02d833-0de4-4a4d-be84-fe71a9bd0582'::uuid]::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id='a15481a7-410b-4a98-8695-3bba0db9d226'::uuid) ORDER BY identity LIMIT 21;
SELECT 'links' AS scope,catalogue_version_id::text||':'||asset_id::text AS identity,to_jsonb(t) AS payload FROM catalog.catalogue_version_assets t WHERE printing_id=any(ARRAY['05ec5ae6-bfb8-41b1-a65b-acb7ce4c3585'::uuid,'56fc9f48-441c-40da-b1a7-29fdbd5300c4'::uuid,'6196aadb-f7bc-4449-8fd3-254987e292f8'::uuid,'ecd63564-d5d4-402d-b28d-95011e2a9107'::uuid,'f03f92e7-086a-4ec9-8281-e3c88906d13d'::uuid]::uuid[]) OR variant_id=any(ARRAY['40806ca5-1d4c-4bf6-b499-cee8ff167f94'::uuid,'767914af-5fcc-4e7c-9304-de89589eb56f'::uuid,'7d0611e3-9b65-4539-8803-c7a9876f6e68'::uuid,'eaa7573e-3860-440e-be69-cb414e6bbda5'::uuid,'fc02d833-0de4-4a4d-be84-fe71a9bd0582'::uuid]::uuid[]) OR asset_id IN (SELECT id FROM catalog.assets WHERE printing_id=any(ARRAY['05ec5ae6-bfb8-41b1-a65b-acb7ce4c3585'::uuid,'56fc9f48-441c-40da-b1a7-29fdbd5300c4'::uuid,'6196aadb-f7bc-4449-8fd3-254987e292f8'::uuid,'ecd63564-d5d4-402d-b28d-95011e2a9107'::uuid,'f03f92e7-086a-4ec9-8281-e3c88906d13d'::uuid]::uuid[]) OR variant_id=any(ARRAY['40806ca5-1d4c-4bf6-b499-cee8ff167f94'::uuid,'767914af-5fcc-4e7c-9304-de89589eb56f'::uuid,'7d0611e3-9b65-4539-8803-c7a9876f6e68'::uuid,'eaa7573e-3860-440e-be69-cb414e6bbda5'::uuid,'fc02d833-0de4-4a4d-be84-fe71a9bd0582'::uuid]::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id='a15481a7-410b-4a98-8695-3bba0db9d226'::uuid)) OR (printing_id IS NULL AND variant_id IS NULL AND set_id='a15481a7-410b-4a98-8695-3bba0db9d226'::uuid) ORDER BY identity LIMIT 21;
SELECT 'sources' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM ingest.sources t WHERE code='scrydex' ORDER BY identity LIMIT 2;
ROLLBACK;
